FROM ecm_product


        AND company_id = #{companyId}


        AND product_nm ILIKE CONCAT('%', #{productNm}, '%')


        AND category_cd = #{categoryCd}


        AND status_cd = #{statusCd}


        AND stock_qty <= 0


        AND stock_qty > 0 AND stock_qty <= #{lowThreshold}


        AND stock_qty > #{lowThreshold}


ORDER BY stock_qty ASC, product_nm ASC, product_id DESC

